using Microsoft.EntityFrameworkCore;using System.Net.Http.Json;
namespace QLNhaTro;
public class PhongTro{public int MaPhong{get;set;}public string TenPhong{get;set;}="";public decimal GiaThue{get;set;}public string TinhTrang{get;set;}="Trống";public List<KhachThue> KhachThues{get;set;}=[];public override string ToString()=>TenPhong;}
public class KhachThue{public int MaKhach{get;set;}public string HoTen{get;set;}="";public string GioiTinh{get;set;}="Nam";public DateTime NgaySinh{get;set;}public string SoDienThoai{get;set;}="";public int MaTinh{get;set;}public string TenTinh{get;set;}="";public int MaPhuongXa{get;set;}public string TenPhuongXa{get;set;}="";public bool DaDangKyTamTru{get;set;}public int MaPhong{get;set;}public PhongTro? PhongTro{get;set;} }
public class NhaTroContext(string cs):DbContext{public DbSet<PhongTro> PhongTros=>Set<PhongTro>();public DbSet<KhachThue> KhachThues=>Set<KhachThue>();protected override void OnConfiguring(DbContextOptionsBuilder b)=>b.UseSqlServer(cs);protected override void OnModelCreating(ModelBuilder b){b.Entity<PhongTro>().ToTable("PhongTro").HasKey(x=>x.MaPhong);b.Entity<KhachThue>().ToTable("KhachThue").HasKey(x=>x.MaKhach);b.Entity<KhachThue>().HasOne(x=>x.PhongTro).WithMany(x=>x.KhachThues).HasForeignKey(x=>x.MaPhong);}}
public sealed class MainForm:Form{static readonly HttpClient http=new(){Timeout=TimeSpan.FromSeconds(10)};readonly NhaTroContext db;readonly TextBox name=new(){Width=170},phone=new(){Width=120},manual=new(){Width=150};readonly ComboBox rooms=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=120},province=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=180},ward=new(){Width=180};readonly DateTimePicker birth=new(){Format=DateTimePickerFormat.Short};readonly CheckBox resident=new(){Text="Đã đăng ký tạm trú"};readonly DataGridView grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect};readonly TextBox search=new(){Width=150};int id;int gender=0;record Addr(int code,string name,List<Addr>? wards=null);public MainForm(string cs){db=new(cs);Text="Quản lý nhà trọ";Width=1100;Height=700;var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=150};p.Controls.AddRange([new Label{Text="Họ tên"},name,new Label{Text="Giới tính"},new RadioButton{Text="Nam",Checked=true},new RadioButton{Text="Nữ"},new Label{Text="Sinh"},birth,new Label{Text="SĐT"},phone,new Label{Text="Phòng"},rooms,new Label{Text="Tỉnh/Thành"},province,new Label{Text="Phường/Xã"},ward,manual,resident]);foreach(var (t,a) in new (string,Action)[]{("Thêm",Add), ("Sửa",Edit),("Xóa",Delete),("Làm mới",Clear),("Bỏ lọc",()=>{search.Clear();rooms.SelectedIndex=-1;province.SelectedIndex=-1;LoadGrid();})}){var b=new Button{Text=t};b.Click+=(_,_)=>a();p.Controls.Add(b);}p.Controls.Add(search);search.TextChanged+=(_,_)=>LoadGrid();rooms.SelectedIndexChanged+=(_,_)=>LoadGrid();province.SelectedIndexChanged+=(_,_)=>LoadGrid();province.SelectedIndexChanged+=async(_,_)=>await LoadWards();ward.TextChanged+=(_,_)=>manual.Visible=!ward.Enabled;grid.SelectionChanged+=(_,_)=>Select();grid.DataError+=(_,_)=>{};Controls.Add(grid);Controls.Add(p);Load+=async(_,_)=>{try{rooms.DataSource=db.PhongTros.AsNoTracking().ToList();grid.DataSource=null;LoadGrid();await LoadProvinces();}catch(Exception e){Serilog.Log.Error(e,"Load error");MessageBox.Show("Không thể kết nối cơ sở dữ liệu.");}};foreach(var r in p.Controls.OfType<RadioButton>())r.CheckedChanged+=(_,_)=>{if(r.Checked)gender=r.Text=="Nữ"?1:0;};}
async Task LoadProvinces(){try{province.Enabled=false;province.Text="Đang tải…";var data=await http.GetFromJsonAsync<List<Addr>>("https://provinces.open-api.vn/api/v2/");province.DataSource=data;province.DisplayMember="name";province.ValueMember="code";}catch(Exception e){Serilog.Log.Warning(e,"Không tải được tỉnh");ward.Enabled=false;manual.Visible=true;MessageBox.Show("Không tải được danh sách địa chỉ, vui lòng kiểm tra mạng");}finally{province.Enabled=true;}}
async Task LoadWards(){if(province.SelectedItem is not Addr a)return;try{ward.Enabled=false;ward.Text="Đang tải…";var full=await http.GetFromJsonAsync<Addr>($"https://provinces.open-api.vn/api/v2/p/{a.code}?depth=2");ward.DataSource=full?.wards;ward.DisplayMember="name";ward.ValueMember="code";manual.Visible=false;}catch(Exception e){Serilog.Log.Warning(e,"Không tải được phường xã");ward.Enabled=false;manual.Visible=true;MessageBox.Show("Không tải được danh sách địa chỉ, vui lòng kiểm tra mạng");}finally{ward.Enabled=true;}}
void LoadGrid(){try{var q=db.KhachThues.Include(x=>x.PhongTro).AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(search.Text)){var s=search.Text.Trim();q=q.Where(x=>x.HoTen.Contains(s)||x.SoDienThoai.Contains(s));}if(rooms.SelectedItem is PhongTro r)q=q.Where(x=>x.MaPhong==r.MaPhong);if(province.SelectedItem is Addr a)q=q.Where(x=>x.MaTinh==a.code);grid.DataSource=q.Select(x=>new{ x.MaKhach,x.HoTen,x.SoDienThoai,Phong=x.PhongTro!.TenPhong,GiaThue=x.PhongTro.GiaThue,QueQuan=x.TenPhuongXa+" – "+x.TenTinh,x.DaDangKyTamTru,x.MaPhong,x.NgaySinh,x.GioiTinh,x.MaTinh,x.TenTinh,x.MaPhuongXa,x.TenPhuongXa}).ToList();}catch(Exception e){Serilog.Log.Error(e,"Grid error");}}
void Select(){if(grid.CurrentRow==null)return;id=Convert.ToInt32(grid.CurrentRow.Cells[nameof(KhachThue.MaKhach)].Value);name.Text=Convert.ToString(grid.CurrentRow.Cells[nameof(KhachThue.HoTen)].Value)??"";phone.Text=Convert.ToString(grid.CurrentRow.Cells[nameof(KhachThue.SoDienThoai)].Value)??"";resident.Checked=Convert.ToBoolean(grid.CurrentRow.Cells[nameof(KhachThue.DaDangKyTamTru)].Value);}
KhachThue Entry()=>new(){HoTen=name.Text.Trim(),SoDienThoai=phone.Text.Trim(),GioiTinh=gender==0?"Nam":"Nữ",NgaySinh=birth.Value.Date,MaPhong=(rooms.SelectedItem as PhongTro)?.MaPhong??0,MaTinh=(province.SelectedItem as Addr)?.code??0,TenTinh=(province.SelectedItem as Addr)?.name??"",MaPhuongXa=(ward.SelectedItem as Addr)?.code??0,TenPhuongXa=(ward.SelectedItem as Addr)?.name??manual.Text.Trim(),DaDangKyTamTru=resident.Checked};
void Add(){var x=Entry();if(x.HoTen==""||x.SoDienThoai==""||x.MaPhong==0){MessageBox.Show("Nhập họ tên, điện thoại và chọn phòng.");return;}try{db.Add(x);var room=db.PhongTros.Find(x.MaPhong)!;room.TinhTrang="Đang thuê";db.SaveChanges();LoadGrid();}catch(Exception e){Serilog.Log.Error(e,"Insert error");MessageBox.Show("Không thể lưu khách thuê.");}}
void Edit(){if(id==0)return;var x=db.KhachThues.Find(id);if(x==null)return;var a=Entry();x.HoTen=a.HoTen;x.SoDienThoai=a.SoDienThoai;x.GioiTinh=a.GioiTinh;x.NgaySinh=a.NgaySinh;x.MaPhong=a.MaPhong;x.MaTinh=a.MaTinh;x.TenTinh=a.TenTinh;x.MaPhuongXa=a.MaPhuongXa;x.TenPhuongXa=a.TenPhuongXa;x.DaDangKyTamTru=a.DaDangKyTamTru;db.SaveChanges();LoadGrid();}
void Delete(){if(id==0||MessageBox.Show("Xóa khách thuê?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;var x=db.KhachThues.Find(id);if(x!=null){int rid=x.MaPhong;db.Remove(x);db.SaveChanges();if(!db.KhachThues.Any(k=>k.MaPhong==rid)){var room=db.PhongTros.Find(rid);if(room!=null)room.TinhTrang="Trống";db.SaveChanges();}LoadGrid();}}
void Clear(){id=0;name.Clear();phone.Clear();birth.Value=DateTime.Today;resident.Checked=false;}}
